const orders = $input.all().map(i => i.json);

const total = orders.reduce((sum, o) => sum + parseFloat(o.total_price || 0), 0);
const pagadas = orders.filter(o => o.financial_status === 'paid').length;
const pendientes = orders.filter(o => o.financial_status === 'pending').length;
const canceladas = orders.filter(o => o.cancelled_at).length;

const fecha = new Date();
fecha.setDate(fecha.getDate() - 1);
const fechaStr = fecha.toLocaleDateString('es-AR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const filas = orders.map(o => {
  const productos = o.line_items.map(l => `${l.quantity}x ${l.name}`).join(', ');
  return `<tr>
    <td style='padding:5px 10px'>#${o.order_number}</td>
    <td style='padding:5px 10px'>${o.billing_address?.first_name || ''} ${o.billing_address?.last_name || ''}</td>
    <td style='padding:5px 10px'>${productos}</td>
    <td style='padding:5px 10px'>ARS ${parseFloat(o.total_price).toLocaleString('es-AR')}</td>
    <td style='padding:5px 10px'>${o.financial_status}</td>
  </tr>`;
}).join('\n');

return [{
  json: {
    fecha: fechaStr,
    totalOrdenes: orders.length,
    totalVentas: total.toLocaleString('es-AR'),
    pagadas,
    pendientes,
    canceladas,
    filas,
    sinOrdenes: orders.length === 0
  }
}];
